describe('Badge count of selected rows', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('[data-testid="table"]').should('be.visible');
  });

  it('should display badge count when rows are selected', () => {
    // Select first row
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '1');

    // Select second row
    cy.get('[data-testid="row-checkbox-1"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '2');

    // Select third row
    cy.get('[data-testid="row-checkbox-2"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '3');
  });

  it('should update badge count when rows are deselected', () => {
    // Select multiple rows
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="row-checkbox-1"]').click();
    cy.get('[data-testid="row-checkbox-2"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '3');

    // Deselect one row
    cy.get('[data-testid="row-checkbox-1"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '2');

    // Deselect another row
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '1');

    // Deselect last row
    cy.get('[data-testid="row-checkbox-2"]').click();
    cy.get('[data-testid="selection-badge"]').should('not.exist');
  });

  it('should handle select all functionality and update badge count', () => {
    // Click select all checkbox
    cy.get('[data-testid="select-all-checkbox"]').click();

    // Get total row count and verify badge matches
    cy.get('[data-testid="table-row"]').then(($rows) => {
      const totalRows = $rows.length;
      cy.get('[data-testid="selection-badge"]').should('contain', totalRows.toString());
    });
  });

  it('should reset badge count when clear selection button is clicked', () => {
    // Select multiple rows
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="row-checkbox-1"]').click();
    cy.get('[data-testid="row-checkbox-2"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '3');

    // Click clear selection button
    cy.get('[data-testid="clear-selection-btn"]').click();

    // Badge should disappear
    cy.get('[data-testid="selection-badge"]').should('not.exist');

    // All checkboxes should be unchecked
    cy.get('[data-testid="row-checkbox-0"]').should('not.be.checked');
    cy.get('[data-testid="row-checkbox-1"]').should('not.be.checked');
    cy.get('[data-testid="row-checkbox-2"]').should('not.be.checked');
  });

  it('should display badge with correct styling and positioning', () => {
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="row-checkbox-1"]').click();

    cy.get('[data-testid="selection-badge"]')
      .should('be.visible')
      .should('have.css', 'position')
      .and('match', /absolute|fixed|relative/);

    cy.get('[data-testid="selection-badge"]')
      .should('have.css', 'background-color')
      .and('not.equal', 'rgba(0, 0, 0, 0)');
  });

  it('should handle edge case with large number of selected rows', () => {
    // Select many rows
    for (let i = 0; i < 50; i++) {
      cy.get(`[data-testid="row-checkbox-${i}"]`).click({ force: true });
    }

    cy.get('[data-testid="selection-badge"]').should('contain', '50');
    cy.get('[data-testid="selection-badge"]').should('be.visible');
  });

  it('should persist badge count during table pagination', () => {
    // Select rows on first page
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="row-checkbox-1"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '2');

    // Navigate to next page
    cy.get('[data-testid="next-page-btn"]').click();
    cy.get('[data-testid="table-row"]').should('be.visible');

    // Select rows on second page
    cy.get('[data-testid="row-checkbox-0"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '3');

    // Navigate back to first page
    cy.get('[data-testid="prev-page-btn"]').click();
    cy.get('[data-testid="selection-badge"]').should('contain', '3');
  });
});
